        shayariItem(568, "शहर में आज सन्नाटा कुछ ज़्यादा है,\nशायद कोई अपना दुनिया छोड़कर जा रहा है।", "_ शायरी", cat, "सन्नाटा"),
        shayariItem(569, "तुम्हारे दिए ज़ख़्म भी साथ ले जा रहा हूँ,\nताकि ऊपर जाकर कोई तुम्हारा नाम न पूछ ले।", "_ शायरी", cat, "वफ़ा"),
        shayariItem(570, "हर इंसान की कहानी का आख़िरी पन्ना एक ही होता है,\nबस किसी की किताब छोटी होती है और किसी की बड़ी।", "_ शायरी", cat, "किताब"),
        shayariItem(571, "नया घर बनाया था बड़े शौक़ से मैंने,\nकिस्मत ने आख़िरकार दो गज़ मिट्टी में ही सुला दिया।", "_ शायरी", cat, "घर"),
        shayariItem(572, "जिनके नाम से दिल धड़कता था कभी,\nउनके आने से पहले ही धड़कन रुक गई।", "_ शायरी", cat, "धड़कन"),
        shayariItem(573, "हँसते हुए जाना है इस दुनिया से यारों,\nरोने के लिए तो पूरी दुनिया बैठी है।", "_ शायरी", cat, "विदाई"),
        shayariItem(574, "आज मेरे दुश्मन भी मुझे बड़ी तमीज़ से देख रहे हैं,\nशायद सफेद चादर ने सारे गिले मिटा दिए।", "_ शायरी", cat, "गिले"),
        shayariItem(575, "मौत से किसको रस्तागारी है मेरे दोस्त,\nआज मेरी बारी है तो कल किसी और की होगी।", "_ शायरी", cat, "बारी"),
        shayariItem(576, "आँखों से आँसू तब सूख जाते हैं,\nजब अपने ही अपने हाथों से आग लगा देते हैं।", "_ शायरी", cat, "अंतिम विदाई"),
        shayariItem(577, "दुनिया के रंगमंच पर बस एक किरदार था मेरा,\nनाटक ख़त्म हुआ और पर्दा गिर गया।", "_ शायरी", cat, "किरदार"),
        shayariItem(578, "कभी सोचा न था इतनी जल्दी सफ़र पूरा होगा,\nअभी तो अपनों से बहुत सी बातें करनी बाकी थीं।", "_ शायरी", cat, "बातें"),
        shayariItem(579, "मेरी कमी तब महसूस होगी तुम्हें,\nजब मेरे नाम की आवाज़ देने पर भी कोई जवाब न आएगा।", "_ शायरी", cat, "कमी"),
        shayariItem(580, "ताले लगे हैं बड़े-बड़े तिजोरियों पर,\nऔर मालिक चुपचाप खाली हाथ श्मशान चला गया।", "_ शायरी", cat, "तिजोरी"),
        shayariItem(581, "जिस वक़्त रूह ने जिस्म छोड़ा,\nउसी पल सारे रिश्तों का नाम 'भूतकाल' हो गया।", "_ शायरी", cat, "वक़्त"),
        shayariItem(582, "कब्र की अंधेरी रात से क्या डरना साहिब,\nजब ज़िंदगी की रौशनी में ही अपनों ने साथ छोड़ दिया हो।", "_ शायरी", cat, "अंधेरा"),
        shayariItem(583, "दो दिन का शोर है मेरे जाने के बाद,\nतीसरे दिन फिर सब अपने कामों में लग जाएँगे।", "_ शायरी", cat, "दुनियादारी"),
        shayariItem(584, "ज़िंदगी ने जो न दिया वो मौत ने दे दिया,\nबिन मांगे ही हमेशा की शांति दे दी।", "_ शायरी", cat, "शांति"),
        shayariItem(585, "मेरे जनाज़े पर ज़्यादा अफ़सोस मत करना,\nबस एक प्यारी सी मुस्कान के साथ अलविदा कह देना।", "_ शायरी", cat, "अलविदा"),
        shayariItem(586, "मिट्टी से बने थे और मिट्टी में ही जा मिले,\nबीच का सफ़र तो बस एक मीठा सपना था।", "_ शायरी", cat, "सपना"),
        shayariItem(587, "साँस लेने की कीमत तब समझ आती है,\nजब कोई हमेशा के लिए साँस लेना बंद कर देता है।", "_ शायरी", cat, "एहसास"),
        shayariItem(588, "जो वक़्त आज अपनों को दे सकते हो दे दो,\nकल फूल माला चढ़ाने से वो लौटकर नहीं आएँगे।", "_ शायरी", cat, "नसीहत"),
        shayariItem(589, "जब उठेगा मेरा जनाज़ा तो आसमान भी रो देगा,\nशायद एक सच्चा दिल आज दुनिया से रुख़सत हो रहा है।", "_ शायरी", cat, "रुख़सती"),
        shayariItem(590, "छोड़ आए हम भी अपने हिस्से के निशान इस ज़मीं पर,\nअब रब की मर्ज़ी जाने और आगे का सफ़र जाने।", "_ शायरी", cat, "निशान"),
        shayariItem(591, "हर साँस एक उधार है ऊपर वाले की,\nजब वो मांगेगा तो खुशी-खुशी लौटाना होगा।", "_ शायरी", cat, "उधार"),
        shayariItem(592, "मेरे जाने की ख़बर सुनकर एक बार तो आ जाना,\nवरना अधूरी रह जाएगी मेरी आख़िरी मुलाक़ात।", "_ शायरी", cat, "मुलाक़ात"),
        shayariItem(593, "कफ़न में लिपटा जिस्म भी यही पैग़ाम देता है,\nज़िंदगी छोटी है इसे प्यार और नेकी में गुज़ारो।", "_ शायरी", cat, "पैग़ाम"),
        shayariItem(594, "ज़माने भर की दौलत भी उस पल बेबस दिखी,\nजब नब्ज़ थमी और डॉक्टर ने सिर झुका लिया।", "_ शायरी", cat, "बेबसी"),
        shayariItem(595, "सब कुछ यहीं छूट जाएगा तेरा और मेरा,\nबस एक नाम और कर्मों का हिसाब रह जाएगा।", "_ शायरी", cat, "हिसाब"),
        shayariItem(596, "अब किसी के आने या जाने से कोई फ़र्क़ नहीं पड़ता,\nहमने अपनी ज़िंदगी को ख़ामोशी के हवाले कर दिया है।", "_ शायरी", cat, "सुकून"),
        shayariItem(597, "सफ़र अच्छा था मगर मंजिल बहुत जल्दी आ गई,\nअलविदा ऐ दुनिया हम तेरी महफ़िल से जा रहे हैं।", "_ शायरी", cat, "विदा"),
        shayariItem(598, "रोशनी कम हुई तो समझ लेना रात हो गई,\nसाँसें थम गईं तो समझ लेना मेरी बात पूरी हो गई।", "_ शायरी", cat, "बात"),
        shayariItem(599, "जब भी मेरी याद आए तो आसमान की ओर देखना,\nकिसी चमकते तारे में मैं तुम्हें मुस्कुराता मिलूँगा।", "_ शायरी", cat, "तारा"),
        shayariItem(600, "आख़िरी सलाम है हर उस शख्स को जिसने प्यार दिया,\nऔर उन्हें भी माफ़ी जिन्होंने दिल पर ज़ख़्म दिया।", "_ शायरी", cat, "आख़िरी सलाम")
    )
}
